Object.entries(detailDictionaries).forEach(([locale, details]) => Object.assign(dictionaries[locale], details));
Object.entries(soulConfigDictionaries).forEach(([locale, details]) => Object.assign(dictionaries[locale], details));
Object.entries(versionHistoryDictionaries).forEach(([locale, details]) => Object.assign(dictionaries[locale], details));

export const MAKER_WORKSPACE_LOCALES = Object.freeze(Object.keys(dictionaries));
export const MAKER_WORKSPACE_KEYS = Object.freeze(Object.keys(en));

export function makerWorkspaceDictionary(locale) {
  return Object.freeze({ ...(dictionaries[locale] || dictionaries.en) });
}

export function makerWorkspaceText(locale, key, variables = {}) {
  const dictionary = dictionaries[locale] || dictionaries.en;
  const template = dictionary[key] || en[key] || key;
  return Object.entries(variables).reduce(
    (result, [name, value]) => result.replaceAll(`{${name}}`, String(value)),
    template,
  );
}
